/** Provides phase19 performance seeder behavior within the WorkIntel application. */ class PerformanceSeeder extends Seeder{/** Handles the run operation for the current WorkIntel workflow. */ public function run():void{if(!Schema::hasTable('performance_goals'))return;$w=Workspace::where('slug','acme-corp')->first();if(!$w)return;$owner=User::where('email','owner@acme.test')->first();$manager=User::where('email','manager@acme.test')->first();$employee=User::where('email','employee@acme.test')->first();$om=$owner?WorkspaceMember::where('workspace_id',$w->id)->where('user_id',$owner->id)->first():null;$mm=$manager?WorkspaceMember::where('workspace_id',$w->id)->where('user_id',$manager->id)->first():null;$em=$employee?WorkspaceMember::where('workspace_id',$w->id)->where('user_id',$employee->id)->first():null;if(!$em||!$om)return;$skills=[];foreach([['Project Planning','Leadership'],['Laravel','Engineering'],['Client Communication','Business']] as [$n,$c])$skills[$n]=Skill::firstOrCreate(['workspace_id'=>$w->id,'name'=>$n],['uuid'=>(string)Str::uuid(),'category'=>$c,'max_proficiency'=>5,'active'=>true]);PerformanceGoal::firstOrCreate(['workspace_id'=>$w->id,'member_id'=>$em->id,'title'=>'Ship Q3 workflow improvements'],['uuid'=>(string)Str::uuid(),'description'=>'Deliver assigned workflow improvements with quality and documentation.','category'=>'individual','status'=>'active','progress_percent'=>45,'weight'=>60,'start_date'=>'2026-08-01','due_date'=>'2026-09-30','created_by'=>$owner->id]);$course=TrainingCourse::firstOrCreate(['workspace_id'=>$w->id,'name'=>'Secure Laravel APIs'],['uuid'=>(string)Str::uuid(),'provider'=>'Internal Academy','duration_hours'=>6,'validity_months'=>12,'status'=>'active']);TrainingEnrollment::firstOrCreate(['course_id'=>$course->id,'member_id'=>$em->id],['workspace_id'=>$w->id,'status'=>'in_progress','assigned_at'=>now(),'started_at'=>now(),'assigned_by'=>$owner->id]);$plan=DevelopmentPlan::firstOrCreate(['workspace_id'=>$w->id,'member_id'=>$em->id,'title'=>'Senior Engineer readiness'],['uuid'=>(string)Str::uuid(),'manager_member_id'=>$mm?->id,'objective'=>'Build technical ownership and mentoring capability.','status'=>'active','start_date'=>'2026-08-01','target_date'=>'2026-12-31']);if($plan->items()->count()===0)$plan->items()->create(['skill_id'=>$skills['Laravel']->id,'title'=>'Lead one production release','status'=>'planned','due_date'=>'2026-10-31']);$cycle=PerformanceReviewCycle::firstOrCreate(['workspace_id'=>$w->id,'name'=>'H2 2026 Performance Review'],['uuid'=>(string)Str::uuid(),'review_type'=>'semiannual','status'=>'active','start_date'=>'2026-08-01','end_date'=>'2026-08-31','self_review_enabled'=>true,'manager_review_enabled'=>true,'questions'=>[['key'=>'impact','question'=>'What impact did you create?'],['key'=>'growth','question'=>'Where will you grow next?']],'created_by'=>$owner->id]);PerformanceReview::firstOrCreate(['cycle_id'=>$cycle->id,'member_id'=>$em->id],['uuid'=>(string)Str::uuid(),'workspace_id'=>$w->id,'manager_member_id'=>$mm?->id,'status'=>'pending']);if($mm)Recognition::firstOrCreate(['workspace_id'=>$w->id,'recipient_member_id'=>$em->id,'sender_member_id'=>$mm->id,'title'=>'Strong release ownership'],['uuid'=>(string)Str::uuid(),'type'=>'kudos','message'=>'Handled the release checklist and follow-up with strong ownership.','points'=>50,'visible_to_team'=>true,'recognized_at'=>now()]);$survey=PulseSurvey::firstOrCreate(['workspace_id'=>$w->id,'title'=>'August Team Pulse'],['uuid'=>(string)Str::uuid(),'description'=>'Short monthly engagement pulse.','status'=>'active','anonymous'=>true,'opens_at'=>now()->subDay(),'closes_at'=>now()->addDays(14),'created_by'=>$owner->id]);if($survey->questions()->count()===0){$survey->questions()->create(['position'=>1,'question'=>'How manageable is your workload?','question_type'=>'rating','required'=>true]);$survey->questions()->create(['position'=>2,'question'=>'What would improve your work this month?','question_type'=>'text','required'=>false]);}$comp=CompensationReviewCycle::firstOrCreate(['workspace_id'=>$w->id,'name'=>'2026 Year-End Compensation'],['uuid'=>(string)Str::uuid(),'start_date'=>'2026-11-01','end_date'=>'2026-12-15','status'=>'draft','currency'=>$w->currency?:'USD','budget_amount'=>50000,'created_by'=>$owner->id]);CompensationReviewItem::firstOrCreate(['cycle_id'=>$comp->id,'member_id'=>$em->id],['workspace_id'=>$w->id,'current_amount'=>null,'proposed_amount'=>null,'currency'=>$comp->currency,'current_title'=>$em->job_title,'proposed_title'=>'Senior Software Engineer','status'=>'draft','justification'=>'Seed proposal for workflow testing.']);}}
